export type ParsedApproveClaimInstruction<
  TProgram extends string = typeof MUTAV_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** The admin (the Squads vault, through the admin time lock). */
    admin: TAccountMetas[0];
    config: TAccountMetas[1];
    guarantee: TAccountMetas[2];
    /**
     * `is_supported` refuses `CLAIM_WITHDRAWN` in this binary (ADR 0019), so
     * an approval never attaches to a withdrawn filing.
     */
    claimFiling: TAccountMetas[3];
    eventAuthority: TAccountMetas[4];
    program: TAccountMetas[5];
  };
  data: ApproveClaimInstructionData;
};

export function parseApproveClaimInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedApproveClaimInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 6) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 6,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      admin: getNextAccount(),
      config: getNextAccount(),
      guarantee: getNextAccount(),
      claimFiling: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getApproveClaimInstructionDataDecoder().decode(instruction.data),
  };
}
